/* SETUP */
VAR _total = [PY_Month_YTD] // Will be used as a target
VAR _value = [Actuals_Month_YTD] // Will be used as a current value

// CANVAS SIZE
VAR _CanvasSize = 350 // Canvas size

// PADDING SETUP
VAR _paddning = 15 // Padding between the circle and the canvas

/* COLOR DEFINITION */
VAR _positive = "#73AE00" // Positive Color
VAR _neutral = "#E7E74E" // Neutral Color
VAR _negative = "#7D1D3A" // Negative Color

/* PRE CALCULATION */
VAR _halfSize = _CanvasSize/2 // Half of the canvas size
VAR _r = _halfSize-_paddning*1.5 // Radius of the circle
VAR _round = 2*PI()*_r
VAR _perc = _value/_total // Percentage of the current value
VAR _ratio = _round-_round*_perc // Ratio of the current value
VAR _clr =  // Determine the color of the circle based on the percentage
    SWITCH(TRUE(),
        _perc>=0.75,_positive, // Positive Color
        _perc>=0.5,_neutral, // Neutral Color
        _positive // Negative Color
    )

/* STYLE DECLARTIONS */
VAR _styles = 
"
  <style>
    text{
        font-family: Segoe UI;
    }
    .backgroundCircle{
      transform:rotate(-90deg) translate(-"&_CanvasSize&"px, 0px);
    }
    .backgroundCircle{
      fill: transparent;
      stroke-width: "&_paddning&";
    }
    .background{
      stroke: #e0e0e0;
    }
    .filling{
      stroke: "&_clr&";
      stroke-linecap: round;
      stroke-dasharray: "&_round&";
      stroke-dashoffset: "&_ratio&";
    }
    .mainText{
      fill: "&_clr&";
      font-size: 250%;
      text-anchor: middle;
      dominant-baseline: middle;
      font-weight: bold;
    }
    .subTexts{
      fill: #CCCCCC;
      font-size: 125%;
      dominant-baseline: middle;
    }
    .leftPositioned{
        text-anchor: end;
    }
    .rightPositioned{
        text-anchor: start;
    }
    .bolden{
        font-weight: bold;
    }
  </style>
"

/* SVG DECLARTIONS */
VAR _svgDeclaration = "data:image/svg+xml;utf8,"
VAR _svgHeader = "<svg xmlns='http://www.w3.org/2000/svg' height='" & _CanvasSize & "' width='" & _CanvasSize & "'>"
VAR _svgEnd = "</svg>"

/* CALCULATION */
VAR _sv =
"
  <g class='backgroundCircle'>
  <circle r='"&_r&"' cx='50%' cy='50%' class='background' />
  <circle r='"&_r&"' cx='50%' cy='50%' class='filling' />
  </g>
  <g class='mainText'>
  <text x='50%' y='40%' >"&FORMAT(_perc,"0.0%")&"</text>
  </g>
  <g class='subTexts'>
  <g class='leftPositioned'>
  <text x='48%' y='52.5%' >"&"Target:"&"</text>
  <text x='48%' y='60%' >"&"Current:"&"</text>

  </g>
  <g class='rightPositioned'>
  <text x='52%' y='52.5%' >"&FORMAT(_total,[format_circle_py])&"</text>
  <text x='52%' y='60%' >"&FORMAT(_value,[format]) & "</text>

  </g>
  </g>
"

VAR _result = _svgDeclaration & _svgHeader & _styles & _sv & _svgEnd 
RETURN
   _result

